with a as(select * from public.authors where open_library_id=any(array['OL10352829A','OL38952A','OL20646A','OL641289A']::text[]) or id=any(array[1654,32,703]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9783442443925','9789053337264','9789029003025','9789035101272']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL547745W','OL14877880W','OL3698638W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['bridgetjonessdiary','dastagebuchderbridgetjones','hetdagboekvanbridgetjones','deprofundis','ondergangen']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['bridgetjonessdiary','dastagebuchderbridgetjones','hetdagboekvanbridgetjones','deprofundis','ondergangen']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987114001 and 987114999),'editions',(select count(*) from public.editions where id between 987214001 and 987214999),'authors',(select count(*) from public.authors where id between 987314001 and 987314999))) as preflight;
